def get_arithmetic_operation():
    """Get user input for the arithmetic operation to perform."""
    operations = {
        "+": "addition",
        "-": "subtraction",
        "*": "multiplication",
        "/": "division",
    }

    while True:
        operation = input("Enter the arithmetic operation (+, -, *, /): ").strip()
        if operation in operations:
            return operation, operations[operation]
        else:
            print("Invalid operation. Please try again.")

def get_numbers():
    """Get user input for the two numbers to perform the operation on."""
    while True:
        try:
            num1 = float(input("Enter the first number: "))
            num2 = float(input("Enter the second number: "))
            return num1, num2
        except ValueError:
            print("Invalid input. Please enter numbers only.")

def perform_operation(num1, num2, operation):
    """Perform the specified arithmetic operation on the two numbers."""
    if operation == "addition":
        result = num1 + num2
    elif operation == "subtraction":
        result = num1 - num2
    elif operation == "multiplication":
        result = num1 * num2
    elif operation == "division":
        if num2 == 0:
            raise ValueError("Division by zero is not allowed.")
        result = num1 / num2
    else:
        raise ValueError(f"Invalid operation: {operation}")

    return result

if __name__ == "__main__":
    operation, operation_name = get_arithmetic_operation()
    num1, num2 = get_numbers()

    try:
        result = perform_operation(num1, num2, operation)
        print(f"{num1} {operation_name} {num2} = {result}")
    except ValueError as e:
        print(e)
